// ❌ Imbrication profonde
String grade(int score) {
    if (score >= 0) {
        if (score <= 100) {
            if (score >= 50) { return "pass"; }
            else { return "fail"; }
        } else { throw new IllegalArgumentException(); }
    } else { throw new IllegalArgumentException(); }
}

// ✅ Gardes en early return, chemin principal à plat
String grade(int score) {
    if (score < 0 || score > 100) throw new IllegalArgumentException();
    return score >= 50 ? "pass" : "fail";
}

// STUB : on teste un ÉTAT de sortie. Le stub fournit une donnée, on vérifie le résultat.
@Test
void applique_la_remise_fidelite() {
    var repo = mock(CustomerRepository.class);
    when(repo.findById(ID)).thenReturn(new Customer(ID, Tier.GOLD)); // stubbing
    var price = new PricingService(repo).quote(ID, 100);
    assertEquals(90, price); // vérification par l'ÉTAT (sortie)
}

// MOCK : on teste une INTERACTION attendue (un email DOIT partir).
@Test
void notifie_le_client_apres_commande() {
    var notifier = mock(Notifier.class);
    new OrderService(notifier).place(anOrder());
    verify(notifier).sendConfirmation(any()); // vérification par le COMPORTEMENT
}
// ⚠️ Trop de verify(...) sur l'ordre exact des appels = test couplé aux détails, fragile.
